	@Test
	void partialWorkerScopeActivationFailureRestoresWorkerReplayScopes() throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		AtomicInteger firstScopeCloses = new AtomicInteger();
		AtomicInteger priorCheckpoints = new AtomicInteger();
		IllegalStateException activationFailure = new IllegalStateException("admission capability expired");
		QueryExecutionContext.ReplayContext replayContext;

		try {
			try (QueryExecutionContext.Activation outer = QueryExecutionContext.activateReplaySafepoint(() -> {
			}, () -> () -> () -> firstScopeCloses.incrementAndGet())) {
				try (QueryExecutionContext.Activation inner = QueryExecutionContext.activateReplaySafepoint(() -> {
				}, () -> () -> {
					throw activationFailure;
				})) {
					replayContext = QueryExecutionContext.captureReplayContext();
				}
			}

			executor.submit(() -> {
				try (QueryExecutionContext.Activation priorSafepoint = QueryExecutionContext
						.activateReplaySafepoint(priorCheckpoints::incrementAndGet)) {
					try (QueryExecutionContext.Activation priorDeferral = QueryExecutionContext
							.deferReplaySafepoints()) {
						assertSame(activationFailure,
								assertThrows(IllegalStateException.class, () -> replayContext.get(() -> null)));
						QueryExecutionContext.checkpointReplaySafepoint();
						assertEquals(0, priorCheckpoints.get(), "the worker's deferral must be restored after failure");
					}
					QueryExecutionContext.checkpointReplaySafepoint();
					assertEquals(1, priorCheckpoints.get(), "the worker's safepoint must be restored after failure");
				}
			}).get(5, TimeUnit.SECONDS);

			assertEquals(1, firstScopeCloses.get(),
					"every successfully activated scope must close after partial failure");
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

