	@Test
	void reusedExecutorDoesNotRetainCapturedWorkerScopes() throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		QueryExecutionContext.ReplayContext firstContext;
		QueryExecutionContext.ReplayContext secondContext;

		try {
			firstContext = captureContext("first-query");
			secondContext = captureContext("second-query");
			Thread worker = executor.submit(() -> {
				return Thread.currentThread();
			}).get(5, TimeUnit.SECONDS);

			executor.submit(() -> {
				assertNull(ACTIVE_WORKER_SCOPE.get());
				firstContext.run(() -> {
					assertSame(worker, Thread.currentThread());
					assertEquals("first-query", ACTIVE_WORKER_SCOPE.get());
				});
				assertNull(ACTIVE_WORKER_SCOPE.get());
				assertNull(QueryExecutionContext.captureReplayContext(),
						"the reused worker must have no captured query state between tasks");

				secondContext.run(() -> {
					assertSame(worker, Thread.currentThread());
					assertEquals("second-query", ACTIVE_WORKER_SCOPE.get());
				});
				assertNull(ACTIVE_WORKER_SCOPE.get());
				assertNull(QueryExecutionContext.captureReplayContext());
			}).get(5, TimeUnit.SECONDS);
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
			ACTIVE_WORKER_SCOPE.remove();
		}
	}

